llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Glycyrrhizin, a highly polar steroid-like saponin, has an oral bioavailability of only ~0.25% in humans, demonstrating that extensive polar substitution can create a severe absorption barrier; the query's six hydroxyl groups and high TPSA align with this low-F direction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Methylprednisolone, a corticosteroid with fewer hydroxyls, has an absolute oral bioavailability of 72.6% from an oral solution, showing that the steroid scaffold can be well absorbed; however, the query's additional polar hydroxyls reduce transferability of this high-F result.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C50"],
      "claim": "Hydrocortisone has an absolute oral bioavailability of 95.9% after oral dosing, another high-F corticosteroid; the query is more polar (six OH groups) than hydrocortisone, so this evidence is only weakly transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Prednisolone oral bioavailability is 78–85% in IBD patients, again high for a corticosteroid; the query's larger polar surface area and extra hydroxyls make this high-F outcome less applicable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly polar polyhydroxylated steroid (ecdysteroid-like) with six H-bond donors and a large polar surface area. Although less polar corticosteroids such as methylprednisolone, hydrocortisone, and prednisolone are well absorbed, the additional hydroxyls are expected to severely limit passive permeability. The low-F glycyrrhizin example supports the absorption barrier for highly polar steroid-related molecules. Therefore, F <20% is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query or a close ecdysteroid analogue.",
    "All retrieved analogues have low Morgan similarity, limiting quantitative transferability.",
    "Possible active transport or first-pass metabolism effects are not directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

